import{_ as t,o as a,c as r,an as i}from"./chunks/framework.CKEzJyyK.js";const c=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md","lastUpdated":null}'),o={name:"getting-started/index.md"};function s(n,e,l,p,d,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started {#getting-started}&quot;">​</a></h1><p>A recurrence computes each value from its own past values, such as infections from earlier infections. A convolution weights the past values of another series, such as reported cases from earlier infections. <a href="/previews/PR774/lib/public#ComposableRecurrences.Recurrence"><code>Recurrence</code></a> and <a href="/previews/PR774/lib/public#ComposableRecurrences.Convolution"><code>Convolution</code></a> are the two operators. Couplings link strata, such as towns, and modifiers add behaviour such as finite pools to each step. Every operator is differentiable.</p><h2 id="Where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#Where-to-start" aria-label="Permalink to &quot;Where to start {#Where-to-start}&quot;">​</a></h2><ul><li><p>New to the package? <a href="/previews/PR774/getting-started/three-towns#tutorial-three-towns">Three towns, step by step</a> builds an outbreak model one part at a time.</p></li><li><p>Looking for an operator, coupling or modifier? See the <a href="/previews/PR774/getting-started/api-overview#api-overview">API overview</a>.</p></li><li><p>Is your data weekly or monthly? See <a href="/previews/PR774/getting-started/time-units#time-units">Time units</a>.</p></li><li><p>Have a model in mind? Each tutorial in this section builds one, starting with <a href="/previews/PR774/getting-started/tutorials/renewal-then-delay#tutorial-renewal-delay">Renewal then delay</a>.</p></li><li><p>Coming from epidemiology? <a href="/previews/PR774/domain-guides/infectious-disease-models#infectious-disease-models">Infectious disease models</a> maps renewal processes, delays and occupancy to the package.</p></li><li><p>Want to know how it works? The Explanation pages start with <a href="/previews/PR774/explanation/operators#explanation-operators">Operators</a>.</p></li><li><p>Want to write your own modifier or coupling? See the <a href="/previews/PR774/developer/index#developer">Developer documentation</a>.</p></li><li><p>Want the full interface? See the <a href="/previews/PR774/lib/public#public-api">Public API</a>.</p></li></ul><h2 id="Getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#Getting-help" aria-label="Permalink to &quot;Getting help {#Getting-help}&quot;">​</a></h2><p>For usage questions, ask on the <a href="https://discourse.julialang.org" target="_blank" rel="noreferrer">Julia Discourse</a> or the <a href="https://community.epinowcast.org" target="_blank" rel="noreferrer">epinowcast community forum</a>, our home for epidemiological modelling questions. Please use <a href="https://github.com/EpiAware/ComposableRecurrences.jl/issues" target="_blank" rel="noreferrer">GitHub issues</a> for bug reports and feature requests only.</p>',6)])])}const g=t(o,[["render",s]]);export{c as __pageData,g as default};
